export default {"/":{"body":"<!doctype html>\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>随看 · 使用统计</title><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/dashboard.css\"><script src=\"/dashboard.js\" defer></script></head>\n<body><main><header><div><p class=\"eyebrow\">SUIKAN / CIN</p><h1>随看使用统计</h1><p>了解有多少人开始使用，又有多少人回来。</p></div><span class=\"badge\">安装实例统计</span></header>\n<section class=\"login\"><label for=\"token\">管理口令</label><div class=\"controls\"><input id=\"token\" type=\"password\" autocomplete=\"off\" placeholder=\"填写部署时设置的管理口令\"><button id=\"load\">查看统计</button><button id=\"clear\" class=\"secondary\">退出</button></div><p class=\"hint\">口令仅保留在当前页面内存中，刷新页面后需重新填写。</p></section>\n<p id=\"status\" role=\"status\">输入管理口令后查看数据。</p>\n<div id=\"report\" hidden><section class=\"metrics\"><article><span>累计首次启动</span><strong id=\"total\">—</strong><small>参与统计的安装实例</small></article><article><span>今日新增</span><strong id=\"new\">—</strong><small>首次使用日期为今天</small></article><article><span>今日活跃 · DAU</span><strong id=\"dau\">—</strong><small>今天打开过应用</small></article><article><span>近 30 天活跃 · MAU</span><strong id=\"mau\">—</strong><small>30 天内去重</small></article></section>\n<section class=\"metrics\"><article><span>累计使用次数</span><strong id=\"total-uses\">—</strong><small>提取与总结任务启动数</small></article><article><span>今日使用次数</span><strong id=\"today-uses\">—</strong><small>按任务开始日期计数</small></article><article><span>累计字幕提取</span><strong id=\"extract-uses\">—</strong><small>包含成功、失败及取消</small></article><article><span>累计视频总结</span><strong id=\"summary-uses\">—</strong><small>包含读取已保存的总结</small></article></section>\n<section class=\"panel\"><h2>功能使用情况</h2><p class=\"hint\">每次实际开始的任务计一次；重复点击但未启动、连接测试和后台刷新不计。结果按完成日期记录，正在运行或被系统终止的任务可能暂时没有结果。</p><div class=\"table-scroll\"><table class=\"usage-table\"><thead><tr><th>功能</th><th>累计使用</th><th>今日使用</th><th>累计成功</th><th>累计失败</th><th>累计取消</th></tr></thead><tbody id=\"operations\"></tbody></table></div></section>\n<section class=\"panel\"><div class=\"section-title\"><h2>近 30 天趋势</h2><span>每日活跃 <i class=\"dot\"></i> / 每日新增 <i class=\"dot pale\"></i></span></div><div id=\"chart\" class=\"chart\" aria-label=\"每日活跃和新增趋势\"></div><details><summary>查看每日数据和使用次数</summary><div class=\"table-scroll\"><table class=\"usage-table\"><thead><tr><th>日期</th><th>活跃</th><th>新增</th><th>字幕提取</th><th>视频总结</th><th>成功</th><th>失败</th><th>取消</th></tr></thead><tbody id=\"daily\"></tbody></table></div></details></section>\n<section class=\"panel\"><h2>最近上报的版本分布</h2><table><thead><tr><th>版本</th><th>安装实例数</th></tr></thead><tbody id=\"versions\"></tbody></table></section>\n<section class=\"panel\"><h2>用户使用权限</h2><p class=\"hint\">按随机安装编号管理。停用阻止新的字幕提取和总结，已有笔记仍可查看和导出。新版 APP 前台每分钟检查一次，正在执行的任务不强行中断。</p>\n<div class=\"controls\"><input id=\"search\" maxlength=\"64\" aria-label=\"安装编号筛选\" placeholder=\"输入安装编号或前缀（小写十六进制）\"><button id=\"filter\" class=\"secondary\">筛选</button></div>\n<div class=\"table-scroll installations\"><table><thead><tr><th>安装编号</th><th>版本</th><th>首次 / 最近使用</th><th>累计使用次数</th><th>状态 / 原因</th><th>操作</th></tr></thead><tbody id=\"installations\"></tbody></table></div>\n<div class=\"pagination\"><span id=\"page-info\"></span><button id=\"previous\" class=\"secondary\">上一页</button><button id=\"next\" class=\"secondary\">下一页</button></div></section></div>\n<dialog id=\"access-dialog\"><h2 id=\"access-title\">修改使用权限</h2><p id=\"access-id\" class=\"identifier\"></p><p id=\"access-description\"></p><label for=\"reason\">停用原因（可选，用户会看到）</label><textarea id=\"reason\" maxlength=\"200\" rows=\"3\"></textarea><div class=\"controls\"><button id=\"confirm-access\">确认停用</button><button id=\"cancel-access\" class=\"secondary\">取消</button></div></dialog>\n<footer>日期按北京时间计算。使用次数从接入统计的 0.1.11 开始累计，旧版历史次数无法补回。离线上报最多保留最近 31 个自然日，失败后等待重试，未上报的数据暂不计入。仅记录随机安装编号、日期、版本和功能次数，不上传视频内容。重装或清除数据会产生新编号，因此安装实例数不等于真实人数，也可以绕过该安装的停用状态。权限管理仅支持接入此后台的新版 APP。</footer></main></body></html>\n","mime":"text/html; charset=utf-8"},"/dashboard.js":{"body":"\"use strict\";\r\nconst byId=id=>document.getElementById(id);\r\nlet token=\"\",request=null,offset=0,selected=null;\r\nconst format=n=>Number(n).toLocaleString(\"zh-CN\");\nconst emptyUsage=()=>({started:0,succeeded:0,failed:0,cancelled:0,extract:{started:0,succeeded:0,failed:0,cancelled:0},summary:{started:0,succeeded:0,failed:0,cancelled:0}});\nfunction cell(row,value){const td=document.createElement(\"td\");td.textContent=value;row.append(td);}\r\nfunction render(data){\r\n  byId(\"total\").textContent=format(data.total_installations);byId(\"new\").textContent=format(data.new_today);\r\n  byId(\"dau\").textContent=format(data.dau);byId(\"mau\").textContent=format(data.mau_30d);\n  const total=data.operations?.total||emptyUsage(),today=data.operations?.today||emptyUsage();\n  byId(\"total-uses\").textContent=format(total.started);byId(\"today-uses\").textContent=format(today.started);\n  byId(\"extract-uses\").textContent=format(total.extract.started);byId(\"summary-uses\").textContent=format(total.summary.started);\n  byId(\"operations\").replaceChildren();\n  for(const [kind,name] of [[\"extract\",\"字幕提取\"],[\"summary\",\"视频总结\"]]){const row=document.createElement(\"tr\");cell(row,name);for(const n of [total[kind].started,today[kind].started,total[kind].succeeded,total[kind].failed,total[kind].cancelled])cell(row,format(n));byId(\"operations\").append(row);}\n  byId(\"daily\").replaceChildren();byId(\"versions\").replaceChildren();byId(\"chart\").replaceChildren();\r\n  const max=Math.max(1,...data.daily.map(d=>Math.max(d.active,d.new)));\r\n  data.daily.forEach((d,index)=>{\r\n    const row=document.createElement(\"tr\"),usage=d.usage||emptyUsage();cell(row,d.day);for(const n of [d.active,d.new,usage.extract.started,usage.summary.started,usage.succeeded,usage.failed,usage.cancelled])cell(row,format(n));byId(\"daily\").prepend(row);\n    const column=document.createElement(\"div\");column.className=\"day-bar\";column.title=`${d.day}：活跃 ${d.active}，新增 ${d.new}`;\r\n    for(const key of [\"active\",\"new\"]){const bar=document.createElement(\"div\");bar.className=key===\"new\"?\"bar new\":\"bar\";bar.style.height=`${d[key]/max*100}%`;column.append(bar);}\r\n    if((index%7===0&&index<27)||index===29){const label=document.createElement(\"span\");label.className=\"day-label\";label.textContent=d.day.slice(5);column.append(label);}byId(\"chart\").append(column);\r\n  });\r\n  data.versions.forEach(v=>{const row=document.createElement(\"tr\");cell(row,v.version);cell(row,format(v.installations));byId(\"versions\").append(row);});\r\n  if(!data.versions.length){const row=document.createElement(\"tr\");cell(row,\"暂无上报\");cell(row,\"0\");byId(\"versions\").append(row);}\r\n  byId(\"report\").hidden=false;byId(\"status\").textContent=`统计日期 ${data.date} · 北京时间 · 刷新时间 ${new Date().toLocaleTimeString(\"zh-CN\")}`;\r\n}\r\nfunction renderInstallations(data){\r\n  offset=data.offset;byId(\"installations\").replaceChildren();\r\n  for(const item of data.items){\r\n    const row=document.createElement(\"tr\");cell(row,item.id);row.lastChild.className=\"identifier\";cell(row,item.app_version);cell(row,`${item.first_day} / ${item.last_day}`);\n    const usage=item.usage||emptyUsage();cell(row,`${format(usage.started)} 次`);const detail=document.createElement(\"span\");detail.className=\"usage-detail\";detail.textContent=`提取 ${format(usage.extract.started)} / 总结 ${format(usage.summary.started)} · 成功 ${format(usage.succeeded)} / 失败 ${format(usage.failed)} / 取消 ${format(usage.cancelled)}`;row.lastChild.append(detail);\n    cell(row,item.enabled?\"可用\":\"已停用\");if(!item.enabled)row.lastChild.className=\"disabled-state\";\r\n    if(item.reason){const reason=document.createElement(\"span\");reason.className=\"access-reason\";reason.textContent=item.reason;row.lastChild.append(reason);}\r\n    const action=document.createElement(\"td\"),button=document.createElement(\"button\");button.textContent=item.enabled?\"停用\":\"恢复\";button.className=\"secondary\";button.addEventListener(\"click\",()=>editAccess(item));action.append(button);row.append(action);byId(\"installations\").append(row);\r\n  }\r\n  if(!data.items.length){const row=document.createElement(\"tr\");cell(row,\"没有匹配的安装记录\");row.firstChild.colSpan=6;byId(\"installations\").append(row);}\n  byId(\"page-info\").textContent=`共 ${format(data.total)} 个安装实例 · 第 ${Math.floor(offset/50)+1} 页`;byId(\"previous\").disabled=offset===0;byId(\"next\").disabled=offset+data.limit>=data.total;\r\n}\r\nfunction editAccess(item){\r\n  selected=item;byId(\"access-title\").textContent=item.enabled?\"停用此安装？\":\"恢复此安装？\";byId(\"access-id\").textContent=item.id;\r\n  byId(\"access-description\").textContent=item.enabled?\"停用后将阻止新的字幕提取和总结；不删除已有笔记。\":\"恢复后允许此安装继续提取字幕和总结。\";\r\n  byId(\"reason\").value=item.reason;byId(\"reason\").disabled=!item.enabled;byId(\"confirm-access\").textContent=item.enabled?\"确认停用\":\"确认恢复\";byId(\"access-dialog\").showModal();\r\n}\r\nasync function api(path,signal,body){\r\n  const headers={Authorization:`Bearer ${token}`};if(body)headers[\"Content-Type\"]=\"application/json\";\r\n  const response=await fetch(path,{method:body?\"POST\":\"GET\",headers,cache:\"no-store\",signal,body:body?JSON.stringify(body):undefined});\r\n  if(!response.ok)throw new Error(response.status===401?\"管理口令不正确。\":response.status===429?\"请求过于频繁，请稍后再试。\":\"管理服务暂时不可用，请刷新确认状态。\");\r\n  return response.json();\r\n}\r\nasync function load(pageOffset=0){\r\n  token=byId(\"token\").value.trim()||token;if(!token){byId(\"status\").textContent=\"请填写管理口令。\";return;}\r\n  if(request)request.abort();request=new AbortController();const current=request;const timeout=setTimeout(()=>current.abort(),15000);\r\n  byId(\"load\").disabled=true;byId(\"report\").hidden=true;byId(\"status\").textContent=\"正在读取统计…\";\r\n  try{\r\n    const query=byId(\"search\").value.trim();if(!/^[0-9a-f]{0,64}$/.test(query))throw new Error(\"安装编号只能包含小写十六进制字符。\");\r\n    const [data,installations]=await Promise.all([api(\"/api/summary\",current.signal),api(`/api/installations?offset=${pageOffset}&limit=50&q=${query}`,current.signal)]);\r\n    if(current!==request)return;byId(\"token\").value=\"\";render(data);renderInstallations(installations);\r\n  }catch(error){if(current===request)byId(\"status\").textContent=error.name===\"AbortError\"?\"请求已取消或超时，请重试。\":error.message;}\r\n  finally{clearTimeout(timeout);if(current===request){request=null;byId(\"load\").disabled=false;}}\r\n}\r\nbyId(\"load\").addEventListener(\"click\",()=>load());byId(\"token\").addEventListener(\"keydown\",event=>{if(event.key===\"Enter\")load();});\r\nbyId(\"clear\").addEventListener(\"click\",()=>{if(request)request.abort();request=null;token=\"\";byId(\"token\").value=\"\";byId(\"report\").hidden=true;for(const id of [\"daily\",\"versions\",\"chart\",\"installations\",\"operations\"])byId(id).replaceChildren();byId(\"access-dialog\").close();selected=null;for(const id of [\"total\",\"new\",\"dau\",\"mau\",\"total-uses\",\"today-uses\",\"extract-uses\",\"summary-uses\"])byId(id).textContent=\"—\";byId(\"load\").disabled=false;byId(\"status\").textContent=\"已退出，页面中的统计数据已清除。\";});\n\r\nbyId(\"filter\").addEventListener(\"click\",()=>load());byId(\"search\").addEventListener(\"keydown\",event=>{if(event.key===\"Enter\")load();});\r\nbyId(\"previous\").addEventListener(\"click\",()=>load(Math.max(0,offset-50)));byId(\"next\").addEventListener(\"click\",()=>load(offset+50));\r\nbyId(\"cancel-access\").addEventListener(\"click\",()=>byId(\"access-dialog\").close());\r\nbyId(\"confirm-access\").addEventListener(\"click\",async()=>{\r\n  if(!selected||request)return;const item=selected,reason=byId(\"reason\").value.trim();byId(\"confirm-access\").disabled=true;\r\n  const current=new AbortController();request=current;const timeout=setTimeout(()=>current.abort(),15000);\r\n  try{await api(\"/api/access\",current.signal,{id:item.id,enabled:!item.enabled,reason});if(current!==request)return;byId(\"access-dialog\").close();selected=null;request=null;await load(offset);}\r\n  catch(error){if(current===request){byId(\"access-dialog\").close();byId(\"status\").textContent=error.name===\"AbortError\"?\"请求超时，请刷新确认权限状态。\":error.message;}}\r\n  finally{clearTimeout(timeout);if(current===request)request=null;byId(\"confirm-access\").disabled=false;}\r\n});\r\n","mime":"text/javascript; charset=utf-8"},"/dashboard.css":{"body":":root{font-family:system-ui,-apple-system,\"Segoe UI\",sans-serif;color:#20232e;background:#f6f7fb;font-synthesis:none}*{box-sizing:border-box}body{margin:0}main{max-width:1100px;margin:auto;padding:48px 24px}header{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:30px}.eyebrow{font-size:12px;letter-spacing:.16em;color:#e83279;font-weight:700}h1{font-size:32px;margin:8px 0}p,footer{color:#6a7081;line-height:1.7}header p{margin:8px 0}.badge{background:#ffe9f1;color:#a82054;border-radius:30px;padding:9px 14px;white-space:nowrap;font-size:13px}.login,.panel,.metrics article{background:white;border:1px solid #e6e8ef;border-radius:18px;padding:24px}.login label{font-size:14px;font-weight:600}.controls{display:flex;gap:10px;margin-top:12px}input{flex:1;min-width:80px;border:1px solid #d7dbe5;border-radius:10px;padding:12px;font-size:15px}button{border:0;border-radius:10px;background:#e83279;color:white;padding:12px 18px;font-size:14px;cursor:pointer}button.secondary{background:#f0f1f6;color:#454b5b}button:disabled{opacity:.55;cursor:wait}.hint{font-size:12px;margin-bottom:0}#status{font-size:14px;min-height:24px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:22px 0}.metrics span{font-size:13px;color:#656b7b}.metrics strong{display:block;font-size:38px;line-height:1.3;margin:15px 0 8px}.metrics small{color:#8a90a0;font-size:11px}.panel{margin:18px 0}h2{font-size:17px;margin:0 0 18px}.section-title{display:flex;justify-content:space-between;align-items:baseline;gap:16px}.section-title span{font-size:12px;color:#777e90}.dot{display:inline-block;background:#e83279;width:8px;height:8px;border-radius:2px}.dot.pale{background:#f9b7d1}.chart{height:210px;display:flex;align-items:stretch;gap:5px;padding:15px 0 24px;border-bottom:1px solid #eee}.day-bar{flex:1;display:flex;align-items:flex-end;justify-content:center;position:relative;gap:2px;min-width:0}.bar{width:45%;min-height:1px;background:#e83279;border-radius:3px 3px 0 0}.bar.new{background:#f9b7d1}.day-label{position:absolute;font-size:10px;color:#9398a5;bottom:-18px;white-space:nowrap}.table-scroll{max-height:300px;overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:14px}th,td{padding:12px 5px;border-bottom:1px solid #f0f1f5}th{color:#747b8c;font-weight:500}details{margin-top:20px}summary{font-size:13px;color:#737b8d;cursor:pointer}footer{font-size:12px;margin-top:25px;max-width:850px}input:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid #e83279;outline-offset:3px}[hidden]{display:none!important}@media(max-width:700px){main{padding:26px 16px}header{align-items:flex-start;flex-direction:column;gap:8px}h1{font-size:27px}.metrics{grid-template-columns:repeat(2,1fr);gap:10px}.metrics article{padding:18px}.metrics strong{font-size:30px}.controls{flex-wrap:wrap}input{flex-basis:100%}.section-title{flex-direction:column;gap:0}.chart{gap:2px}.panel{padding:18px}}\n:root dialog{border:1px solid #e6e8ef;border-radius:18px;max-width:480px;width:calc(100% - 32px);padding:24px}dialog::backdrop{background:#20232e66}textarea{display:block;width:100%;margin-top:10px;border:1px solid #d7dbe5;border-radius:10px;padding:12px;font:inherit;resize:vertical}.identifier{font-family:monospace;overflow-wrap:anywhere;font-size:12px}.installations{max-height:520px;margin-top:18px}.installations table{min-width:700px}.installations td{vertical-align:top}.installations .identifier{max-width:210px;min-width:150px}.access-reason{display:block;max-width:180px;overflow-wrap:anywhere;font-size:12px;margin-top:5px;color:#747b8c}.disabled-state{color:#b32559;font-weight:600}.pagination{display:flex;align-items:center;justify-content:flex-end;gap:10px;margin-top:16px;flex-wrap:wrap}.pagination span{margin-right:auto;font-size:13px;color:#747b8c}dialog label{font-size:13px}\n.usage-table{min-width:640px}.usage-detail{display:block;min-width:155px;max-width:210px;font-size:12px;color:#747b8c;line-height:1.6;margin-top:5px}.panel>.hint{margin-bottom:16px}.installations table{min-width:900px}\n","mime":"text/css; charset=utf-8"},"/favicon.svg":{"body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"18\" fill=\"#e83279\"/><path d=\"m26 19 21 13-21 13z\" fill=\"#fff\"/></svg>\n","mime":"image/svg+xml"}};
